    "s21_category": "Teil 3: Hammerkopf-Produktion • Vorformung",
    "s21_title": "Vorformung des Bassfilzes & Biegekurven",
    "s21_subtitle": "Ausbildung der charakteristischen Spannungsbögen vor dem Schließen der Presse",
    "s21_bullet_1": "<strong>Elastische Vorbiegung:</strong> Das dicke Bass-Ende des Filzstreifens wird vor dem Einbringen in die Pressform vorkonditioniert.",
    "s21_bullet_2": "<strong>Charakteristische Kurven:</strong> Entlang des Streifens bilden sich harmonische Wellen, die den späteren Druckfluss abbilden.",
    "s21_bullet_3": "<strong>Gleichmäßige Dehnung:</strong> Verhindert das Reißen äußerer Faserlagen beim engen Umschließen der Kernholzspitze.",
    "s21_caption_1": "Bass-Ende des Filzstreifens mit charakteristischen Biegekurven vor dem Pressen",
    "s21_b1_badge": "VORFORMUNG",
    "s21_b2_badge": "BIEGEKRAFT",
    "s21_notes": "Folie 21: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s22_category": "Teil 3: Hammerkopf-Produktion • Pressprozess",
    "s22_title": "Pressen & Verleimen: Zug- und Druckkräfte im Filz",
    "s22_subtitle": "Nachspannen des Kernholzes zur Erzeugung maximaler elastischer Außenspannung",
    "s22_bullet_1": "<strong>Schließen der Seitenbacken:</strong> Die temperierten Pressbacken umschließen den Filz seitlich und führen ihn um das beleimte Kernholz.",
    "s22_bullet_2": "<strong>Kernholz nachspannen:</strong> Nachdem die Seitenbacken geschlossen sind, wird das Kernholz nochmals mit Hochdruck nachgespannt.",
    "s22_bullet_3": "<strong>Zugspannung in den Außenlagen:</strong> Durch diesen Renner-spezifischen Schritt erhalten die äußeren Filzlagen eine unerreichte Vorspannung.",
    "s22_bullet_4": "<strong>Basis für die spätere Intonation:</strong> Diese elastische Eigenspannung erlaubt späteres Intonieren mit unvergleichlicher Dynamikspreizung.",
    "s22_caption_1": "Press- und Verleimvorgang des Hammerkopfs unter Hochdruck",
