    "s23_category": "Teil 3: Hammerkopf-Produktion • Hammerkopf-Riegel",
    "s23_title": "Der Hammerkopf-Riegel im Rohzustand",
    "s23_subtitle": "Entformung des monolithischen 88er-Riegels nach dem Aushärten des Leims",
    "s23_bullet_1": "<strong>Perfekte Leimfuge:</strong> Vollflächige Verbindung zwischen Holz, Unterfilz und Deckfilz ohne Lufteinschlüsse.",
    "s23_bullet_2": "<strong>Harmonischer Übergang:</strong> Die Kernform zeichnet sich präzise unter dem komprimierten Filz ab.",
    "s23_bullet_3": "<strong>Betriebsgeheimnis der Formgebung:</strong> Bestimmte nachgelagerte Warmformschritte unterliegen dem strengen Renner-Verfahrensschutz.",
    "s23_caption_1": "Der verleimte Hammerkopf-Riegel direkt nach dem Entformen",
    "s23_b1_badge": "RIEGEL-FERTIGUNG",
    "s23_b2_badge": "PRESS-RIEGEL",
    "s23_c1_desc": "Nach dem kontrollierten Abkühlen und Abbinden des Leims wird der Hammerkopf als zusammenhängender Riegel entnommen.",
    "s23_notes": "Folie 23: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s24_category": "Teil 3: Hammerkopf-Produktion • CNC-Bearbeitung",
    "s24_title": "CNC-Bearbeitung & Abrichten des Riegels",
    "s24_subtitle": "Mehrachsiges Fräsen der Flanken und Trennen in 88 Einzelexemplare",
    "s24_bullet_1": "<strong>CNC-Abrichten der Leisten:</strong> Beseitigung von Leimaustritten und exaktes Ausfräsen der Außenradien.",
    "s24_bullet_2": "<strong>Hochgeschwindigkeits-Fräsen:</strong> Spezialwerkzeuge schneiden den dichten Wollfilz mit rasiermesserscharfen Kanten ohne Faserausriss.",
    "s24_bullet_3": "<strong>Präzises Auftrennen:</strong> Trennen des Riegels in exakt abgestimmte Breiten (Bass ca. 11,5 mm bis Diskant ca. 9,5–10 mm).",
    "s24_caption_1": "CNC-Präzisionsfräszentrum in Meuselwitz bei der Leistenbearbeitung",
    "s24_b1_badge": "CNC-ABRICHTEN",
    "s24_b2_badge": "CNC-FRÄSUNG",
    "s24_notes": "Folie 24: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s25_category": "Teil 3: Hammerkopf-Produktion • Bohren & Vernieten",
    "s25_title": "Bohrung, T-Vernietung & Veredelung",
    "s25_subtitle": "Präzise Stielbohrung im Raumwinkel und formschlüssige Messing-T-Niete",
    "s25_bullet_1": "<strong>Automatisierte Stielbohrung:</strong> Bohren im exakten Raumwinkel (Bohrungslänge, Durchmesser ø 5,4 mm, Neigungswinkel in Gon).",
    "s25_bullet_2": "<strong>T-Vernietung (Riveting):</strong> Hochfeste Messing-T-Nieten sichern die Filzschenkel dauerhaft gegen Aufplatzen bei stärksten Konzertanschlägen.",
    "s25_bullet_3": "<strong>Verrundung der Hammerschwänze:</strong> Speziell geformte Radien am Schwanz erleichtern später das Einpassen in den Fänger.",
    "s25_caption_1": "Bohren und Einbringen der T-Nieten in Meuselwitz",
    "s25_b1_badge": "VEREDELUNG & ENDBEARBEITUNG",
    "s25_b2_badge": "WERKSVIDEO",
    "s25_notes": "Folie 25: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s26_category": "Teil 3: Hammerkopf-Produktion • Qualität & Nutzen",
    "s26_title": "Die 6 Kernvorteile der neuen Renner-Hammerköpfe",
    "s26_subtitle": "Zusammenfassung der Innovationskraft aus dem Vortrag von Clemens Kunert",
    "s26_c1_title": "1. Maßgeschneiderte Fertigung",
    "s26_c2_title": "2. Direkt fertig zur Endintonation",
    "s26_c3_title": "3. Höchste Fertigungspräzision",
    "s26_c4_title": "4. Überragende Klangstabilität",
    "s26_c5_title": "5. Reiches Obertonspektrum",
    "s26_c6_title": "6. Einbaufertig veredelt",
    "s26_c1_desc": "Individuelle Sonderanfertigung von Einzelstücken für historische Schätze bis hin zu großen Konzert-Serien.",
    "s26_c2_desc": "Keine zeitraubende Vorintonation am Instrument mehr nötig! Der Satz ist ab Werk klanglich vorbereitet.",
    "s26_c3_desc": "Kombination aus traditionellem FFW-Filzhandwerk und mikrometergenauer Roboter- und CNC-Bearbeitung.",
    "s26_c4_desc": "Durch die Eigenspannung des Weickert-Special-Filzes bleibt das Klangbild über viele Jahre hinweg stabil.",
    "s26_c5_desc": "Breiteste Dynamikspreizung vom zartesten Pianissimo bis zum tragfähigen Fortissimo im großen Konzertsaal.",
    "s26_c6_desc": "Präzise gebohrt, formschlüssig vernietet, mit verrundeten Schwanzenden und veredelter Scheitelkontur.",
    "s26_b1_badge": "MASSGESCHNEIDERT",
    "s26_b2_badge": "EFFIZIENZ",
    "s26_b3_badge": "PRÄZISION",
    "s26_b4_badge": "STABILITÄT",
    "s26_b5_badge": "OBERTONREICH",
    "s26_b6_badge": "EINBAUFERTIG",
    "s26_notes": "Folie 26: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s27_category": "Teil 4: Yamaha Kit • Produktvorstellung",
    "s27_title": "Louis Renner Yamaha Kit (C1–C3)<br>Nahtloser Einbau & Maximale Klangveredelung",
    "s27_subtitle": "Maßgeschneidert für Yamaha C1–C3: Dynamische Ausdruckskraft, brillante Obertöne & tiefer Fundamentalbass.",
    "s27_play_label": "Präsentation abspielen",
    "s27_tab1_tag": "Messbasiertes System",
    "s27_tab2_tag": "Gewicht & Dynamik",
