    "s16_subtitle": "Razor-sharp vertical cuts prevent skewed stretching during hammer moulding",
    "s16_bullet_1": "<strong>100% Vertical Cut Edge:</strong> Prevents distortion and uneven fiber elongation during subsequent high-pressure pressing.",
    "s16_bullet_2": "<strong>No Crushed Fibers:</strong> Clean cutting preserves internal fiber voids, ensuring unconstrained compression dynamics.",
    "s16_bullet_3": "<strong>Prevention of Skewing:</strong> Only strictly rectangular cut strips wrap around the wooden moulding with absolute lateral symmetry.",
