    "s26_c2_desc": "No time-consuming pre-voicing required at the piano! Sets arrive tonally pre-conditioned from the factory.",
    "s26_c3_desc": "Combining traditional FFW felt mastery with micrometer-level robotic and CNC precision.",
    "s26_c4_desc": "Thanks to the stored tension of Weickert Special felt, tonal response remains rock-solid for years.",
