    "s27_category": "Part 4: Yamaha Kit • Product Showcase",
    "s27_title": "Louis Renner Yamaha Kit (C1–C3)<br>Seamless Drop-In & Acoustic Excellence",
    "s27_subtitle": "Tailored for Yamaha C1–C3: Dynamic expressiveness, brilliant overtones & deep fundamental bass.",
