    "s27_tab5_tag": "Hours Instead of Days",
    "s27_b1_badge": ">MEASUREMENT-BASED PRODUCTION · 5 YEARS R&D",
    "s27_p1_title": "Proprietary Measurement & Production System",
    "s27_p1_subtitle": "Supreme voicing culture for new and existing Yamaha C1–C3 grand pianos.",
    "s27_p1_bullet_1": "<strong>Calibrated System:</strong> 5 years of R&D for perfectly tuned felt density, elasticity, and tension.",
    "s27_p1_bullet_2": "<strong>Defined Target Tone:</strong> Every set manufactured to millimeter precision for the C1–C3 acoustic optimum.",
    "s27_p1_bullet_3": "<strong>Tone Without Needling:</strong> Instant full, warm concert sound – zero manual pre-voicing needed.",
    "s27_p1_fact": "✦ Reliable Concert Tone: Instant master result straight from the factory",
    "s27_b2_badge": ">RENNER MEASUREMENT SYSTEM",
    "s27_p1_caption": "Calibrated hammer set: Complete harmonic spectrum without manual needling",
    "s27_b3_badge": ">OPTIMIZED INERTIA",
    "s27_p2_title": "Balanced Weight & Fast Repetition",
    "s27_p2_subtitle": "Calibrated walnut core with fine-grained shanks for noticeably lighter key response.",
    "s27_p2_bullet_1": "<strong>Calibrated Walnut Core:</strong> Light resonance core reduces inertia for agile, effortless playing.",
    "s27_p2_bullet_2": "<strong>Selected Hornbeam:</strong> Fine-grained quarter-sawn wood guarantees maximum stiffness and pure vibration.",
    "s27_p2_bullet_3": "<strong>Pre-Tensioned Knuckles:</strong> Glued under high tension for superior resilience and instant repetition.",
    "s27_p2_fact": "✦ Massive Time Savings: Complete replacement & regulation in 4–5 hours on site",
    "s27_b4_badge": ">WEIGHT & GEOMETRY",
    "s27_p2_caption": "Calibrated hammer shanks with flanges for Yamaha C1–C3 providing sensitive touch",
    "s27_b5_badge": ">SCREW IN · ALIGN · DONE",
    "s27_p3_title": "Simply screw in, align, done.",
    "s27_p3_subtitle": "Fully pre-glued set on flanges – factory-bonded with natural gluten glue.",
    "s27_p3_bullet_1": "<strong>1-Screw Mounting:</strong> Custom flanges screw note by note directly into the original Yamaha rail.",
    "s27_p3_bullet_2": "<strong>Pre-Bored Accuracy:</strong> Pre-drilled at the exact angle – zero measuring or boring in the workshop.",
    "s27_p3_bullet_3": "<strong>Rock-Hard Gluten Glue:</strong> Crystallizes glass-hard for direct, undamped vibration transfer into the shank.",
    "s27_p3_fact": "✦ Peak Process Reliability: Zero risk of drilling or gluing errors",
    "s27_b6_badge": ">PLUG & PLAY",
    "s27_p3_caption": "Pre-glued at 91° angle on shanks – screws directly onto original Yamaha rail",
    "s27_b7_badge": ">HARMONIC-RICH CONCERT TONE",
    "s27_p4_title": "Rich Harmonic Spectrum & Color",
    "s27_p4_subtitle": "From warm European pianissimo to powerful projection in fortissimo.",
    "s27_p4_bullet_1": "<strong>Seamless Felt Strip:</strong> Milled from a single piece — guarantees seamless transitions across all 88 keys.",
    "s27_p4_bullet_2": "<strong>Articulated Bass:</strong> Balanced mass and resilient felt for deep fundamental tone and clean note separation.",
    "s27_p4_bullet_3": "<strong>Bell-Clear Treble:</strong> Lightweight core and targeted crown compression for a singing, carrying treble tone.",
    "s27_p4_fact": "✦ Acoustic Elevation: Transforms harsh attack into warm, singing concert tone",
    "s27_b8_badge": ">DYNAMICS & TIMBRE",
    "s27_p4_caption": "Milled from a single continuous felt sheet: Seamless register transitions",
    "s27_b9_badge": ">HOURS INSTEAD OF DAYS",
    "s27_p5_title": "4–5 Hours on Site Instead of 3–7 Workshop Days",
    "s27_p5_subtitle": "Traditional multi-day workshop procedure versus same-day installation and regulation on site.",
    "s27_p5_bullet_1": "<strong>Traditional (3–7 Days):</strong> Transport, ungluing, boring chart, hot glue, aligning, sanding & pre-voicing.",
    "s27_p5_bullet_2": "<strong>Renner Kit (4–5 h):</strong> Bolt on directly, align string level and crown – finish voicing if desired.",
    "s27_p5_bullet_3": "<strong>On-Site & Room Acoustics:</strong> Zero transport risk — more time to tailor the sound to room acoustics and customer wishes.",
    "s27_p5_fact": "✦ Peak Economic Efficiency: Work reduced from days to a few hours on site",
    "s27_b10_badge": ">EFFICIENCY COMPARISON",
    "s27_p5_caption": "Worn factory hammer after 25 years vs. brand new Renner concert head on shank",
    "s27_b11_badge": ">RENNER YAMAHA KIT",
    "s27_spotlight_badge": ">RENNER YAMAHA KIT",
    "s27_c1_title": "Heads & Shanks in Detail",
    "s27_spotlight_title": "Heads & Shanks in Detail",
    "s27_c1_desc": "100% drop-in pre-assembled for Yamaha C1, C2, and C3.",
    "s27_spotlight_desc": "100% drop-in pre-assembled for Yamaha C1, C2, and C3.",
    "s27_texture_tag": "Macro: Head on Shank with Flange",
    "s27_zoom_btn": "🔍 Macro Zoom",
    "s27_hl1_title": "Calibrated System:",
    "s27_hl1_desc": "Proprietary measurement process for finished sound straight from the factory.",
    "s27_hl2_title": "Walnut & Hornbeam:",
    "s27_hl2_desc": "Minimized moment of inertia for lightning-fast repetition and agile response.",
    "s27_hl3_title": "Drop-In & Gluten Glue:",
    "s27_hl3_desc": "Rock-hard 91° acoustic coupling, factory pre-glued – 0 h drilling labor.",
    "s27_hl4_title": "1-Screw Installation:",
    "s27_hl4_desc": "Plug & play into original rail – installation & regulation in 4–5 hours on site.",
    "s27_notes": "Slide 27: Emphasize the core innovation: 5 years of R&D creating a proprietary measurement and production system. Renner produces hammerheads calibrated to a precise acoustic spectrum, outperforming factory hammers on brand-new Yamaha C1–C3 grands without needle voicing. Highlight the reassurance for technicians without daily voicing routine: the kit eliminates all risk. Together with 1-screw installation and pre-tensioned knuckles, workshop time drops from 3–7 days to just 4–5 hours on site with superior repetition. The piano stays with the customer, giving the technician time to fine-tune directly to the room acoustics and customer preferences.",
    "s28_category": "Part 5: Voicing • Geometrie & Keile",
    "s28_title": "The Clock Model: The 4 Dynamic Wedges",
    "s28_subtitle": "Structured hammerhead zoning by register and dynamic objectives",
    "s28_b1_badge": "FORTISSIMO (ff)",
    "s28_b2_badge": "FORTE (f)",
    "s28_b3_badge": "PIANO (p)",
