    "s28_c1_title": "Blue Wedge",
    "s28_c2_title": "Green Wedge",
    "s28_c3_title": "Orange Wedge",
    "s28_c4_title": "Violet Wedge",
    "s28_c5_title": "DO NOT TOUCH! – Never prick deeply here!",
    "s28_c1_desc": "Deep needle stitches for tension release",
    "s28_c2_desc": "Projection, brilliance, and dynamic blossoming",
    "s28_c3_desc": "Lyrical singing tone, nuanced balance",
    "s28_c4_desc": "Whisper-soft pianissimo response",
    "s28_caption_1": "Original Renner Clock Model",
    "s28_caption_2": "with the 4 dynamic wedges (ff, f, p, pp)",
    "s28_notes": "Slide 38: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s29_category": "Part 5: Voicing • Vorintonation",
    "s29_title": "Pre-Voicing (Pre-Needling): Deep 90° Stitches in Blue Wedge",
    "s29_subtitle": "Relieving factory pre-tension and channeling elastic energy into the forte wedge",
    "s29_bullet_1": "<strong>Work Zone:</strong> Exclusively in the blue fortissimo wedge (clock zones 9:00–10:00 and 2:00–3:00).",
    "s29_bullet_2": "<strong>Deep Needling:</strong> Insert needles deeply to just short of the underfelt (never pierce underfelt or core wood!).",
    "s29_bullet_3": "<strong>Tension Transfer:</strong> The head sheds rigid factory stiffness; stored tension flows into the green forte wedge.",
    "s29_bullet_4": "<strong>Recommendation:</strong> This step is recommended almost without exception prior to first playing-in in the instrument.",
    "s29_caption_1": "Pre-needling: Deep stitches in the fortissimo wedge (9:00 to 10:00 o'clock)",
    "s29_b1_badge": "PRE-NEEDLING",
    "s29_b2_badge": "BASIC ELASTICITY",
    "s29_c1_desc": "Pre-voicing is the single most critical foundation for brand-new or refelted hammerheads:",
    "s29_notes": "Slide 39: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s30_category": "Part 5: Voicing • Werkzeug & Technik",
    "s30_title": "Needle Insertion Standards & Voicing Tools",
    "s30_subtitle": "Press, do not chop – Exact stitch counts for bass, mid-range, and treble",
    "s30_bullet_1": "<strong>Stitch Counts for Pre-Needling:</strong> <br>• Bass: 7–10 stitches horizontally <br>• Mid-Range: 5–10 stitches horizontally <br>• Treble: 0–7 stitches vertically",
    "s30_bullet_2": "<strong>Press, never chop!</strong> Press needles steadily using body weight. Chopping tears wool fibers uncontrollably!",
    "s30_bullet_3": "<strong>Original Renner Tools:</strong> <br>• Adjustable Voicing Tool (item 43-0005642) <br>• 3-Needle Voicing Tool Professional (item 43-0003270) <br>• Nickel-plated needles no. 7 ø 0.60 mm, 9 mm long (item 43-0003426).",
    "s30_caption_1": "Renner voicing tools, needle handles, and adjustable voicing instrument",
    "s30_b1_badge": "TOOL SET",
    "s30_b2_badge": "PRECISION NEEDLES",
    "s30_notes": "Slide 40: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s31_category": "Part 5: Voicing • Saitenlagerung",
    "s31_title": "String Preparation: Hitch Pins, Bridge Pins & Leveling",
    "s31_subtitle": "“The finest hammerhead can only reveal what is programmed into the instrument!”",
    "s31_caption_1": "Bedding strings firmly at the hitch pin using brass drift punch",
    "s31_b1_badge": "STRING BEDDING",
    "s31_b2_badge": "UNISON PURITY",
    "s31_bullet_1": "<strong>Setting Hitch Pins:</strong> Carefully seat strings from back to front at hitch pins using a brass drift punch and light hammer.",
    "s31_bullet_2": "<strong>Bridge Pin Alignment:</strong> Seat strings on the bridge with Renner bridge punch to eliminate false beats.",
    "s31_bullet_3": "<strong>Unison Purity:</strong> Before the first voicing needle, the unison must ring absolutely pure and free of unwanted friction.",
    "s31_notes": "Slide 41: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s32_category": "Part 5: Voicing • Ausrichtung",
    "s32_title": "Treble Strike Point Alignment & Hammer Straightness",
    "s32_subtitle": "Optimizing notes 69–88 by micro-shifting the keyframe strike line",
    "s32_bullet_1": "<strong>Test Strike Point on Note 88:</strong> Shift keyframe slightly forward and back to locate the brightest, most singing treble sweet spot.",
    "s32_bullet_2": "<strong>Optimize Notes 69 to 88:</strong> The high treble on many grands improves dramatically once the strike line is precisely repositioned!",
    "s32_bullet_3": "<strong>Squareness of All Hammers:</strong> Test by plucking strings or lifting jacks with finger; mark corrections with chalk on key tops.",
    "s32_caption_1": "Verifying treble strike point and square alignment of hammerheads",
    "s32_b1_badge": "STRIKE POINT",
    "s32_b2_badge": "TREBLE BRILLIANCE",
    "s32_notes": "Slide 42: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s33_category": "Part 5: Voicing • Kronenabzug",
    "s33_title": "Crown Filing: Concave, Correct or Tilted",
    "s33_subtitle": "Adapting the strike crown to the 3-string unison using a fine hammer file",
    "s33_c1_title": "Hollow Crown",
    "s33_c2_title": "Crooked Crown",
    "s33_c3_title": "Level & Symmetrical (Crown OK)",
    "s33_c1_desc": "Crown contacts only outer strings -> incomplete attack tone, must be filed level.",
    "s33_c2_desc": "Asymmetrical contact creates double attack and string buzz -> file true to string plane.",
    "s33_c3_desc": "Simultaneous solid contact on all 3 unison strings for a full fundamental tone.",
    "s33_caption_1": "Filing hammer crowns for perfect flush alignment to 3-string unisons",
    "s33_b1_badge": "HOLLOW BEFORE ROUND",
    "s33_b2_badge": "CROWN APEX",
    "s33_b3_badge": ">SANDING PADDLE",
    "s33_notes": "Slide 43: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s34_category": "Part 5: Voicing • Feinabstimmung",
    "s34_title": "Intermediate & Fine Voicing: The 2 mm Limit at the Crown",
    "s34_subtitle": "Chromatic listening and delicate evening-out of individual notes",
    "s34_bullet_1": "<strong>Chromatic Play-Through:</strong> Play chromatically up and down the keyboard; flag notes with harsh attack or uneven volume.",
    "s34_bullet_2": "<strong>Mid-Voicing:</strong> Gentle needle pricks in green forte and orange piano wedges. Overly soft notes are firmed by light surface sanding!",
    "s34_bullet_3": "<strong>Final Voicing:</strong> Short single needle (BDK handle item 43-0003269 or Chop Stick item 43-0003271).",
    "s34_bullet_4": "<strong>Max. 2 mm Depth at Crown:</strong> Insert only between string grooves, never directly into the string depressions!",
    "s34_caption_1": "Chromatic listening and fine voicing with short single needle",
    "s34_b1_badge": "FINE VOICING",
    "s34_b2_badge": "COLOR PALETTE",
    "s34_notes": "Slide 44: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s35_category": "Part 5: Voicing • Una Corda & Dialog",
    "s35_title": "Shift Pedal Voicing (Una Corda) & Renner Technical Dialogue",
    "s35_subtitle": "Voicing the una corda pedal, eliminating noise & welcome to the Renner dialogue",
    "s35_b1_badge": "UNA CORDA PRACTICE",
    "s35_b2_badge": "RENNER ACADEMY",
    "s35_b3_badge": "LOUIS RENNER GMBH",
    "s35_c1_title": "Shift Pedal Voicing (Una Corda)",
    "s35_c2_title": "Renner Academy & Technical Dialogue",
    "s35_c1_desc": "Play chromatically with shift pedal depressed; gently voice only the contacted string contact areas.",
    "s35_c2_desc": "Renner provides masterclasses, factory tours in Meuselwitz, and tailored technical support for piano technicians worldwide.",
