    "s5_m6_title": "「ヴァイケルト・シュペツィアル」復刻とレンナー提携",
    "s5_m6_subtitle": "ヴルツェン伝統工場とレンナー・モイゼルヴィッツ本工場との緊密な隣接関係",
    "s5_m6_bullet_1": "<strong>2010年伝統復刻：</strong>ブラント家が1903年の伝説的特級配合を完全再現し、世界最高峰の響きが復活。",
    "s5_m6_bullet_2": "<strong>至近距離（わずか65km）：</strong>ヴルツェンとレンナー・モイゼルヴィッツ工場は中部ドイツ伝統クラスター内で隣接。",
    "s5_m6_bullet_3": "<strong>職人同士の直接対話：</strong>わずか1時間の距離が、フェルト職人とハンマー技師の密接な現地共同調音を実現。",
    "s5_m6_fact": "📍 わずか65km：ヴルツェン ↔ レンナー・モイゼルヴィッツの直接提携",
    "s5_m6_caption": "ヴルツェン製ヴァイケルト・シュペツィアル：究極の整音性と豊かな響き",
