    "s5_hl1_desc": "アルゼンチン、南アフリカ、ニュージーランド産原毛を厳選ブレンド：長く繊細な高級羊毛と強固に絡み合う捲縮羊毛の絶妙な組み合わせが、極めて高い引張強度と弾性を持つハンマーフェルトを生み出します。",
