    "s21_category": "第3部：精密ハンマーヘッド製造工程",
    "s21_title": "低音部フェルトの予備成形と曲げテンション",
    "s21_subtitle": "Ausbildung der charakteristischen Spannungsbögen vor dem Schließen der Presse",
    "s21_bullet_1": "<strong>Elastische Vorbiegung:</strong> Das dicke Bass-Ende des Filzstreifens wird vor dem Einbringen in die Pressform vorkonditioniert.",
    "s21_bullet_2": "<strong>Charakteristische Kurven:</strong> Entlang des Streifens bilden sich harmonische Wellen, die den späteren Druckfluss abbilden.",
    "s21_bullet_3": "<strong>Gleichmäßige Dehnung:</strong> Verhindert das Reißen äußerer Faserlagen beim engen Umschließen der Kernholzspitze.",
    "s21_caption_1": "Bass-Ende des Filzstreifens mit charakteristischen Biegekurven vor dem Pressen",
    "s21_b1_badge": "予備成形",
    "s21_b2_badge": "曲げ応力",
