    "s25_category": "第3部：精密ハンマーヘッド製造工程",
    "s25_title": "精密ボウリング（穴あけ）・T字ワイヤーカシメ・研磨",
    "s25_subtitle": "Präzise Stielbohrung im Raumwinkel und formschlüssige Messing-T-Niete",
    "s25_bullet_1": "<strong>Automatisierte Stielbohrung:</strong> Bohren im exakten Raumwinkel (Bohrungslänge, Durchmesser ø 5,4 mm, Neigungswinkel in Gon).",
    "s25_bullet_2": "<strong>T-Vernietung (Riveting):</strong> Hochfeste Messing-T-Nieten sichern die Filzschenkel dauerhaft gegen Aufplatzen bei stärksten Konzertanschlägen.",
    "s25_bullet_3": "<strong>Verrundung der Hammerschwänze:</strong> Speziell geformte Radien am Schwanz erleichtern später das Einpassen in den Fänger.",
    "s25_caption_1": "Bohren und Einbringen der T-Nieten in Meuselwitz",
