    "conf_badge": "2025年研讨峰会 • 北京与丰桥",
    "rotate_device_title": "请旋转设备至横屏",
    "rotate_device_desc": "路易斯·雷诺大师课专为横屏展示优化，请将设备切换至横向模式。",
    "vox_play": "播放时间轴",
