    "s3_frequency_load": "✦ 莫伊瑟尔维茨 2026 • 正在同步加载频率...",
    "s1_title": "LOUIS RENNER",
    "s1_subtitle": "钢琴的心脏：雷诺140年极致工艺传承、莫伊瑟尔维茨新总部启航与弦槌声学生产大师课",
    "s1_kicker": "雷诺大师课与行业技术峰会 2025 • 北京 & 丰桥",
    "s1_location": "北京 & 丰桥 峰会 2025",
    "s1_notes": "第 1 页：欢迎各位北京与丰桥钢琴业界的贵宾。主讲人克莱门斯·库内特介绍德国雷诺公司。强调2025/2026年雷诺新总部在莫伊瑟尔维茨全面整合的划时代意义。",
    "s2_category": "第一部分：引言与莫伊瑟尔维茨新总部",
    "s2_title": "雷诺大师课五大核心技术模块",
    "s2_subtitle": "基于雷诺原厂大师学院权威技术文献的完整专业培训体系",
    "s2_b1_badge": "第1章",
    "s2_b2_badge": "第2章",
    "s2_b3_badge": "第3章",
    "s2_b4_badge": "第4章",
    "s2_b5_badge": "第5章",
    "s2_c1_title": "历史积淀与现代辉煌",
    "s2_c2_title": "毛毡制造工艺与百年传统",
    "s2_c3_title": "高精弦槌精密制造",
    "s2_c4_title": "雅马哈定制套件（C1-C3）",
    "s2_c5_title": "极致声音整音艺术",
    "s2_c1_desc": "140余年厚重历史、生产基地全面整合及莫伊瑟尔维茨全新总部。",
    "s2_c2_desc": "始于1783年的FFW与魏克特传统、纯美利奴羊毛、天然缩绒（硬度Shore 0.56）与雷诺专属Weickert Special特制琴毡。",
    "s2_c3_desc": "机器人智能裁毡、底毡精铣、梯级芯木（密度490–860 kg/m³）、吨位冷压、五轴CNC精密成型与防开裂T型固芯铆接。",
    "s2_c4_desc": "雅马哈三角琴即插即用升级：单螺丝极速固定，节省约10小时台架工时，免去打孔上胶，开箱即享音乐会级共鸣。",
    "s2_c5_desc": "时钟表盘整音法、四层动态音色扇区（ff, f, p, pp）、预刺针、三弦平整度校准、槌顶弧度修整与左踏板弱音极细调谐。",
    "s2_notes": "第 2 页：介绍大师课五大核心技术模块：品牌历史与莫伊瑟尔维茨新总部、德国顶尖纯羊毛毡制造工艺、高精弦槌精密制造、重磅新品雅马哈高定套件（Yamaha KIT），以及极致声音整音艺术。",
    "s3_category": "第一部分：引言与莫伊瑟尔维茨新总部",
    "s3_title": "140余年德国制造荣耀与传奇传承（1882年至今）",
    "s3_subtitle": "从斯图加特手工小作坊跃升为享誉全球的顶级钢琴击弦机与弦槌第一品牌",
    "s3_notes": "第 3 页：140余年荣耀时光轴（共9个关键里程碑）。重点阐述里程碑 1（1882年：斯图加特匠心工坊创立 — 击弦机开启百年传奇之旅；与卡尔·罗尼施全铸铁铠装音板的历史呼应）、里程碑 2（1906年：开启声学核心部件弦槌自主生产 — 从1700年克里斯托弗里皮革包裹纸卷弦槌到1906年雷诺自产弦槌，日后定义了每一架施坦威三角钢琴的独特音色并确立全球工业标准；克里斯托弗里、1700年早期击弦机、早期手工车间与1906年专用压力模具全景图集）、里程碑 3（1911年：工业电化革命与三角钢琴击弦机 — 传承埃拉尔复奏结构现代演奏之基石；迈向雷诺首批三角击弦机自主生产；奥斯卡·雷诺推进专用精密机床、工序优化并以数百台独立电机单驱彻底替代传统总轴皮带；全谱系制造完美闭环；埃拉尔、1808年结构与工业电化车间全景图集）、里程碑 4（1944年空袭重生）、里程碑 5（1951/1952年：曼弗雷德·雷诺博士）、里程碑 6（1990年：柏林墙倒塌与雷诺生死存亡之战 — 收购蔡茨击弦机基地以抵御捷克厂商冲击，力挽日产逾40架钢琴的第一大客户舒密尔）、里程碑 7（2011年：盖特林根新厂落成与从蔡茨迁至莫伊瑟尔维茨后的现代化核心制造基地；莫伊瑟尔维茨6,800平米与盖特林根双基地格局；盖特林根新总部与鸟瞰莫伊瑟尔维茨生产基地全景图集）、里程碑 8（2019年：施坦威集团收购与深切缅怀阿尔尼姆先生）以及里程碑 9（恪守传统 · 塑造未来：2025年10月启动的莫伊瑟尔维茨全流程整合圆满收官，落成全新现代化中央过滤排风吸附系统，并向盖特灵根团队致以深切谢意）。",
    "s4_category": "第一部分：引言与莫伊瑟尔维茨新总部",
