    "s5_m1_bullet_1": "<strong>1783年创立：</strong>约翰·丹克戈特·魏克特在乌尔岑奠定萨克森羊毛与高级制毡工艺传统。",
    "s5_m1_bullet_2": "<strong>精细毛毡先驱：</strong>传统手工工坊迅速壮大为欧洲顶尖的高端工业技术与声学纯羊毛毡制造中心。",
    "s5_m1_bullet_3": "<strong>深耕钢琴声学：</strong>极早专注于为方兴未艾的现代钢琴研制高弹性专属击弦介质。",
    "s5_m1_fact": "🏛 位于乌尔岑的全球历史最悠久工业羊毛毡制造企业",
    "s5_m1_caption": "从手工梳理的原生态羊毛薄毡到极高密度的魏克特专用整块毡料",
    "s5_m2_badge": "发明 1847",
    "s5_m2_title": "德国首创高品质工业钢琴弦槌毛毡",
    "s5_m2_subtitle": "帕茨克与魏克特于1847年颠覆欧洲传统钢琴击弦工艺",
    "s5_m2_bullet_1": "<strong>毛毡取代皮革：</strong>1847年首次成功以均质高弹性纯羊毛毡彻底替代坚硬不均的传统皮革包裹。",
    "s5_m2_bullet_2": "<strong>大师级卓越协同：</strong>魏克特的远见卓识与帕茨克的精湛制毡技艺强强联合，铸就全球声誉。",
    "s5_m2_bullet_3": "<strong>穆尔德河天然水质：</strong>穆尔德河矿物质极低的天然纯净软水，确保羊毛纤维得到最温和的纯净处理。",
    "s5_m2_fact": "🎹 行业里程碑：乌尔岑特级琴毡终结钢琴皮革击弦时代",
    "s5_m2_caption": "格尔策恩水磨坊旧址（1850年）：在穆尔德河中孤岛建立早期制毡工场",
    "s5_m3_badge": "享誉全球 1851",
    "s5_m3_title": "伦敦与巴黎世博会揽获世界金奖",
    "s5_m3_subtitle": "享誉国际并获萨克森王室御赐殊荣的至高毛毡品质",
    "s5_m3_bullet_1": "<strong>揽获世博金奖：</strong>接连斩获莱比锡（1850）、伦敦（1851）与巴黎（1867）最高世博金奖，名满天下。",
    "s5_m3_bullet_2": "<strong>国王亲临视察：</strong>萨克森王国历代君主亲临视察乌尔岑制造工场，盛赞其卓绝工艺。",
    "s5_m3_bullet_3": "<strong>欧洲名厂一致之选：</strong>维也纳、巴黎与伦敦的顶级钢琴制造大师全线指定采用魏克特毛毡。",
    "s5_m3_fact": "🏅 1851伦敦、1867巴黎及1850莱比锡世博金牌",
    "s5_m3_caption": "因极致毛毡工艺与纯净度而荣获的历史世博会珍藏金牌",
    "s5_m4_badge": "扩张 1861",
    "s5_m4_title": "乌尔岑水渠沿岸工业化大规模扩产",
    "s5_m4_subtitle": "蒸汽动力、现代化高效缩绒机组与穆尔德纯净软水汇聚",
    "s5_m4_bullet_1": "<strong>规模化现代工厂：</strong>1861年在乌尔岑水渠旁落成自备蒸汽动力机房的现代化大跨度厂区。",
    "s5_m4_bullet_2": "<strong>高精缩绒机群：</strong>专属蒸汽动力大型缩绒设备确保毛毡具备绝佳的密度梯度与极其严苛的批次稳定性。",
    "s5_m4_bullet_3": "<strong>温和洗毛保护：</strong>极软天然活水完美呵护美利奴初剪羊毛表面的天然微观角质鳞片。",
