    "s5_m5_subtitle": "帕茨克厂长、制毡大师团队与350名高级技师（1906年）",
    "s5_m5_bullet_1": "<strong>独霸全球市场：</strong>乌尔岑每年为全球20万架三角与立式钢琴独家供应高品质弦槌毛毡。",
    "s5_m5_bullet_2": "<strong>全球统一标杆：</strong>施坦威纽约总厂及欧洲各大顶级音乐会制造大师一致指定乌尔岑琴毡。",
    "s5_m5_bullet_3": "<strong>大师团队与帕茨克厂长：</strong>1906年历史原始档案照：与巨型梯级阶梯压制毛毡原板合影。",
