    "s5_m6_bullet_2": "<strong>近邻优势（仅相距65公里）：</strong>乌尔岑与雷诺迈泽尔维茨同处德国中部深厚钢琴制造核心产业腹地。",
    "s5_m6_bullet_3": "<strong>面对面大师协同：</strong>极短路程实现制毡大师与弦槌技师现场即时深度调校，精准定制最佳密度与弹性。",
