    "s27_category": "第四部分：雅马哈套件 • 产品专场",
    "s27_title": "德国雷诺雅马哈升级套件（C1-C3）<br>极速无缝换装与巅峰音乐会音质",
    "s27_subtitle": "专为雅马哈C1-C3量身定制：宏大的动态表现力、清澈通透的泛音与深沉浑厚的基频低音。",
    "s27_play_label": "自动演示",
    "s27_tab1_tag": "科学测量系统",
    "s27_tab2_tag": "配重与灵敏手感",
    "s27_tab3_tag": "拧入并对齐",
    "s27_tab4_tag": "音乐会级音色",
    "s27_tab5_tag": "工时大幅缩减",
    "s27_b1_badge": ">科学测量制造体系 · 五年研发攻坚",
    "s27_p1_title": "专有科学测量与生产闭环系统",
    "s27_p1_subtitle": "为新出厂及现有雅马哈C1–C3三角钢琴注入至高声音艺术。",
    "s27_p1_bullet_1": "<strong>科学标定闭环：</strong>历经五年研发，精密标定羊毛毡密度、弹性与张力参数。",
    "s27_p1_bullet_2": "<strong>确定性黄金音色：</strong>以毫米级极高精度精准匹配C1–C3的声学黄金频段。",
    "s27_p1_bullet_3": "<strong>告别繁琐扎针：</strong>出厂即呈现温润饱满的音乐会音质，彻底免除繁琐预整音。",
    "s27_p1_fact": "✦ 可靠音乐会品质：出厂即达大师级终极音质",
    "s27_b2_badge": ">雷诺高精度测量系统",
    "s27_p1_caption": "出厂科学标定高级槌头总成：无需手工扎针即享饱满音色",
    "s27_b3_badge": ">优化转动惯量",
    "s27_p2_title": "完美配重平衡与疾速连击性能",
    "s27_p2_subtitle": "标定胡桃木芯与精选角树槌柄，带来更加轻盈敏捷的触键响应。",
    "s27_p2_bullet_1": "<strong>标定胡桃木芯：</strong>轻量化共鸣木芯大幅降低转动惯量，击键轻松敏锐。",
    "s27_p2_bullet_2": "<strong>精选欧洲白角树：</strong>细密径切木确保极高刚度与纯净击弦能量传导。",
    "s27_p2_bullet_3": "<strong>高预紧力滚柱：</strong>出厂高张力胶合，回弹复位弹性优异，实现顶杆零延迟复奏。",
    "s27_p2_fact": "✦ 极致高效：仅需4–5小时即可在客户现场完成整套换装与精密调校",
    "s27_b4_badge": ">配重与几何力学",
    "s27_p2_caption": "专为雅马哈C1-C3精准标定的槌柄与轴架总成，带来敏捷细腻的触键反馈",
    "s27_b5_badge": ">拧入固定 · 校正对齐 · 交付完成",
    "s27_p3_title": "轻松拧入，校准对齐，即刻交付。",
    "s27_p3_subtitle": "出厂预粘接轴架总成 — 采用天然热骨胶坚固粘结。",
    "s27_p3_bullet_1": "<strong>单螺丝原位锁固：</strong>严丝合缝匹配雅马哈铝合金总档，单颗螺丝逐音直接锁紧。",
    "s27_p3_bullet_2": "<strong>精准出厂预钻孔：</strong>按黄金倾角精准预钻孔 — 彻底免除工坊繁琐夹具测量与钻孔。",
    "s27_p3_bullet_3": "<strong>特制纯天然骨胶：</strong>固化后坚硬如晶体，击弦震动零损耗直通槌柄与琴体。",
    "s27_p3_fact": "✦ 极致工艺可靠度：消除钻孔偏斜与脱胶一切风险",
    "s27_b6_badge": ">即插即用",
    "s27_p3_caption": "以91°黄金角度出厂预装胶合的总成，直接锁紧于雅马哈原装铝轨",
    "s27_b7_badge": ">泛音饱满的音乐会级声学境界",
    "s27_p4_title": "丰富和谐的声学生理与音色层次",
    "s27_p4_subtitle": "自欧洲传统温润细腻的弱奏（pp），至极具穿透力与张力的强奏（ff）。",
    "s27_p4_bullet_1": "<strong>一体化连续羊毛毡：</strong>由单根完整毛毡条三维冲压成型，确保全键盘88键音区无缝过渡。",
    "s27_p4_bullet_2": "<strong>高清晰深沉低音：</strong>严苛质量配比赋予沉稳基音，特级高弹毛毡使每个低音轮廓清晰分明。",
    "s27_p4_bullet_3": "<strong>纯净高音通透如钟：</strong>超轻木芯与槌冠顶端精密高密度压缩，释放悠扬持久的歌唱音色。",
    "s27_p4_fact": "✦ 钢琴声学升华：将生硬敲击声彻底转化为温暖、醇厚且穿透力极强的音乐会音色",
    "s27_b8_badge": ">丰富动态与音色",
    "s27_p4_caption": "由单根完整羊毛毡条一体加工而成：全音区平滑过渡，绝无音色断层",
    "s27_b9_badge": ">工时大幅缩减",
    "s27_p5_title": "从工坊耗费3–7天，精简至现场仅需4–5小时",
    "s27_p5_subtitle": "传统数天繁复车间翻新 vs 客户现场当天极速换装与精密调整。",
    "s27_p5_bullet_1": "<strong>传统翻新（3–7天）：</strong>琴机返厂、旧头脱胶、钻孔制表、热胶找平、繁琐打磨修圆与预整音。",
    "s27_p5_bullet_2": "<strong>雷诺套件（4–5小时）：</strong>直接原位锁紧，对准弦平面与槌冠 — 槌头出厂已打磨，直接终调交付。",
    "s27_p5_bullet_3": "<strong>现场定制与房间声学：</strong>零运输刮蹭风险 — 技师可专注于结合现场房间声学与客户审美定制音色。",
    "s27_p5_fact": "✦ 颠覆性商业经济性：将耗时数天的车间工时压缩至现场数小时极速交付",
    "s27_b10_badge": ">工时效率对比",
    "s27_p5_caption": "使用25年严重凹陷发硬的原装旧槌（右） vs. 乌尔岑特级羊毛毡全新雷诺音乐会槌头（左）",
    "s27_b11_badge": ">德国雷诺雅马哈定制套件",
    "s27_spotlight_badge": ">德国雷诺雅马哈定制套件",
    "s27_c1_title": "槌头与槌柄构造剖析",
    "s27_spotlight_title": "槌头与槌柄构造剖析",
    "s27_c1_desc": "专为雅马哈C1、C2与C3型号量身打造的100%预装直配总成。",
    "s27_spotlight_desc": "专为雅马哈C1、C2与C3型号量身打造的100%预装直配总成。",
    "s27_texture_tag": "微距特写：带轴架的槌头总成",
    "s27_zoom_btn": "🔍 放大镜观察",
    "s27_hl1_title": "科学标定系统：",
    "s27_hl1_desc": "专有高精测量工法，出厂即享成熟饱满音质，无需现场繁复预整音。",
    "s27_hl2_title": "胡桃木与白角树：",
    "s27_hl2_desc": "转动惯量极小化，赋予极速精准连击性能与敏锐触键反馈。",
    "s27_hl3_title": "即插即用与天然骨胶：",
    "s27_hl3_desc": "91°出厂热骨胶结晶刚性胶合，零衰减能量传导，车间钻孔工时归零。",
    "s27_hl4_title": "单螺丝极速换装：",
    "s27_hl4_desc": "原装总档原位即插即用 — 现场仅需4–5小时即可完成全套换装与精细调校。",
    "s27_notes": "第 27 页：重点阐述核心技术突破：历经五年研发的专有测量与生产闭环系统。雷诺能够精确将琴槌标定在黄金声学频段，其音质甚至超越全新出厂的雅马哈原装琴槌，且完全无需扎针预整音。特别强调对非专职整音技师的兜底保障：零失误风险。配合单颗螺丝即插即用与高预紧力滚柱，将3-7天的车间繁复工序缩减至4-5小时现场极速交付，连击复奏性能大幅飞跃。钢琴原地升级无运输风险，技师可专注于房间声学与客户定制化音色塑造。",
    "s28_category": "第七部分：钢琴整音大师秘籍",
    "s28_title": "表盘时钟声学模型：弦槌四大力度动态弹性楔区（ff, f, p, pp）",
    "s28_subtitle": "Strukturierte Aufteilung des Hammerkopfs nach Register- und Lautstärkezielen",
