    "s28_c5_title": "DO NOT TOUCH! – Niemals tief einstechen!",
    "s28_c1_desc": "Tiefe Nadelstiche zur Entspannung",
    "s28_c2_desc": "Raumklang, Glanz und dynamische Entfaltung",
    "s28_c3_desc": "Lyrischer Gesangston, feine Abstimmung",
    "s28_c4_desc": "Flüsterleise Ansprache",
    "s28_caption_1": "Original Renner Uhrenmodell",
    "s28_caption_2": "mit den 4 dynamischen Keilen (ff, f, p, pp)",
    "s28_notes": "第 58 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s29_category": "第七部分：钢琴整音大师秘籍",
    "s29_title": "初期预整音（Pre-Needling）：蓝色极强音楔区深度垂直扎针释放死应力",
    "s29_subtitle": "Abbau werkseitiger Vorspannung und Energieübertragung in den Forte-Keil",
    "s29_bullet_1": "<strong>Arbeitszone:</strong> Ausschließlich im blauen Fortissimo-Keil (Bereiche 9:00–10:00 Uhr und 2:00–3:00 Uhr).",
    "s29_bullet_2": "<strong>Tiefe Einstiche:</strong> Nadeln tief bis kurz vor den Unterfilz einstechen (niemals in Unterfilz oder Holzkern stechen!).",
    "s29_bullet_3": "<strong>Spannungstransfer:</strong> Der Kopf verliert die harte Werkssteife; elastische Spannungsenergie fließt in den grünen Forte-Keil ab.",
    "s29_bullet_4": "<strong>Empfehlung:</strong> Dieser Schritt ist vor dem ersten Anspielen im Instrument fast ausnahmslos anzuraten.",
    "s29_caption_1": "Pre-Needling: Tiefe Stiche im Fortissimo-Keil (9:00 bis 10:00 Uhr)",
    "s29_b1_badge": "基础刺针整音",
    "s29_b2_badge": "建立核心弹性",
    "s29_c1_desc": "预整音是全新出厂或重新包毡弦槌建立健康弹性基座的最核心声学工序：",
    "s29_notes": "第 59 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s30_category": "第七部分：钢琴整音大师秘籍",
    "s30_title": "进针深度、角度与专业排针/单针整音工具规范",
    "s30_subtitle": "Drücken statt Hacken – Exakte Stichanzahlen für Bass, Mittellage und Diskant",
    "s30_bullet_1": "<strong>Stichanzahlen Pre-Needling:</strong> <br>• Bass: 7–10 Stiche horizontal <br>• Mittellage: 5–10 Stiche horizontal <br>• Diskant: 0–7 Stiche vertikal",
    "s30_bullet_2": "<strong>Drücken, niemals hacken!</strong> Nadeln ruhig und mit Körpergewicht eindrücken. Hacken zerreißt die Wollfasern unkontrolliert!",
    "s30_bullet_3": "<strong>Original Renner Werkzeuge:</strong> <br>• Intonierapparat verstellbar (Art. 43-0005642) <br>• 3er-Intonierer Profi-Typ (Art. 43-0003270) <br>• Nadeln Nr. 7 vernickelt ø 0,60 mm, 9 mm lang (Art. 43-0003426).",
    "s30_caption_1": "Renner Intonierwerkzeuge, Nadelhalter und Intonierapparat",
    "s30_b1_badge": "专业整音工具",
    "s30_b2_badge": "进口精密排针",
    "s30_notes": "第 60 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s31_category": "第七部分：钢琴整音大师秘籍",
    "s31_title": "弦列声学校准：弦枕销敲实、挂弦销紧固与同音弦三弦同高平整",
    "s31_subtitle": "„Der beste Hammerkopf kann nur das hervorbringen, was im Instrument programmiert ist!“",
    "s31_caption_1": "Saiten niederschlagen am Anhangstift mit Messingdurchschlag",
    "s31_b1_badge": "琴弦沉实就位",
    "s31_b2_badge": "三弦同音纯净",
    "s31_bullet_1": "<strong>挂弦钉沉降：</strong> 用黄铜冲头和轻手锤将琴弦自后向前轻敲至挂弦钉根部沉实。",
    "s31_bullet_2": "<strong>弦码钉就位：</strong> 使用专用敲合器使琴弦紧贴弦码，消除假杂音与拍音。",
    "s31_bullet_3": "<strong>同音同轴纯净度：</strong> 首次刺针整音前，三根同音弦必须调校至完全纯净、绝无杂音。",
    "s31_notes": "第 61 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s32_category": "第七部分：钢琴整音大师秘籍",
    "s32_title": "高音区击弦点最佳纵深定位与弦槌三弦垂直平行对准",
    "s32_subtitle": "Optimierung der Noten 69–88 durch Verschieben des Klaviaturrahmens",
    "s32_bullet_1": "<strong>Anschlagspunkt Note 88 prüfen:</strong> Klaviaturrahmen minimal vor- und zurückschieben, um die hellste, tragfähigste Klangstelle im Diskant zu finden.",
    "s32_bullet_2": "<strong>Noten 69 bis 88 anpassen:</strong> Der Diskant vieler Flügel lässt sich durch eine Neujustierung des Anschlagspunkts dramatisch verbessern!",
    "s32_bullet_3": "<strong>Geradheit aller Köpfe:</strong> Prüfung durch leichtes Anzupfen mit Haken oder Heben der Klinke mit dem Finger; Markierung mit Kreide auf der Taste.",
    "s32_caption_1": "Prüfung des Diskant-Anschlagspunkts und Ausrichtung der Hämmer",
    "s32_b1_badge": "最佳击弦点",
    "s32_b2_badge": "高音晶莹通透",
    "s32_notes": "第 62 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s33_category": "第七部分：钢琴整音大师秘籍",
    "s33_title": "槌顶打磨整形（Filing）：凹陷、偏斜与饱满平滑弧度的正确砂光",
    "s33_subtitle": "Anpassung der Scheitelfläche an den 3-chörigen Saitenverlauf mit feiner Hammerfeile",
    "s33_c1_title": "Hohlkehle (Hollow Crown)",
    "s33_c2_title": "Schiefe Krone (Crooked Crown)",
    "s33_c3_title": "Plan & Symmetrisch (Crown OK)",
    "s33_c1_desc": "Scheitel trifft nur die Randsaiten -> unvollständiger Ton, muss plan nachgefeilt werden.",
    "s33_c2_desc": "Einseitiges Treffen führt zu doppelter Attacke und Saitenbrummen -> fluchtend beiziehen.",
    "s33_c3_desc": "Gleichzeitiger, satter Anschlag auf alle 3 Saiten des Chors für vollen Grundton.",
    "s33_caption_1": "Feilen der Hammerkrone zur perfekten Ausrichtung auf den 3-Saiten-Chor",
    "s33_b1_badge": "修磨技法",
    "s33_b2_badge": "槌顶圆弧",
    "s33_b3_badge": ">弧度打磨修整板",
    "s33_notes": "第 63 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s34_category": "第七部分：钢琴整音大师秘籍",
    "s34_title": "过渡微调与精细整音：槌顶击弦点表层严控2mm以内浅挑原则",
    "s34_subtitle": "Chromatisches Durchhören und vorsichtiges Egalisieren von Einzeltönen",
    "s34_bullet_1": "<strong>Chromatisches Durchspielen:</strong> Tastatur auf- und abwärts chromatisch anschlagen; Noten mit abweichender Härte oder Lautstärke lokalisieren.",
    "s34_bullet_2": "<strong>Zwischenintonation (Mid-Voicing):</strong> Sanftes Nadeln im grünen Forte- und orangenen Piano-Keil. Zu weiche Töne werden durch feines Nachschleifen gehärtet!",
    "s34_bullet_3": "<strong>Feinintonation (Final Balance):</strong> Kurze Einzelnadel (BDK-Halter Art. 43-0003269 oder Chop Stick Art. 43-0003271).",
    "s34_bullet_4": "<strong>Stichtiefe max. 2 mm an der Krone:</strong> Ausschließlich zwischen den Saitenabdrücken einstechen, niemals direkt in den Rillen!",
    "s34_caption_1": "Chromatisches Abhören und Feinabstimmung mit kurzer Einzelnadel",
    "s34_b1_badge": "精细色彩调配",
    "s34_b2_badge": "全音域色彩平衡",
    "s34_notes": "第 64 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
